56	    void
57	    CHAOSArmTLB::startup()
58	    {
59	        // D1 fix: snapshot the firstClock/lastClock window as sim ticks at
60	        // startup (the global tick domain is fixed by then). The TLB is not
61	        // a ClockedObject, so firstClock/lastClock are interpreted as SIM
62	        // TICKS (curTick domain) — NOT CPU cycles. This removes the prior
63	        // "advisory only, never checked" gap (D1) and the 1GHz * 1000
64	        // assumption used by the sibling CHAOSArmSysReg (D4, fixed
65	        // separately). last_clock==0 means unrestricted (consistent with
66	        // lastClock==0 elsewhere).
67	        first_tick = (Tick)first_clock;
68	        last_tick = (last_clock == Cycles(0)) ? (Tick)0 : (Tick)last_clock;
69	    }
