92	    uint64_t
93	    CHAOSArmTLB::generateRandomMask(int bits_to_change) {
94	        uint64_t mask = 0;
95	        std::uniform_int_distribution<int> bitDist(0, 63);
96	        while (bits_to_change-- > 0) mask |= (1ULL << bitDist(rng));
97	        return mask;
98	    }
