                    << " overwritten=" << (overwrite_recorded ? 1 : 0)
                    << (overwrite_recorded ? (" at_cycle=" + std::to_string(overwritten_at_cycle)) : "")
                    << " (workload halted)"
                    << std::endl;
            }
            cpu->physRegFile().clearReadTraceTarget();
            traced_phys_idx = -1;
        }
    }

