99	    void
100	    CHAOSRenameMap::attackCheck()
101	    {
102	        if (!probability) return;
103	        uint64_t before = faults_injected_count;
104	        for (ThreadID tid = 0; tid < cpu->numThreads; ++tid) {
105	            gem5::ThreadContext *thread_context = cpu->getContext(tid);
106	            if (!thread_context || thread_context->status() == ThreadContext::Halted)
107	                continue;
108	            processFault(tid);
109	        }
110	        if (max_faults == 0 || faults_injected_count < max_faults) {
111	            // method1-formal fix: when an attempt was REJECTED (no donor /
112	            // legality), geometric(1.0) yields a 0-cycle interval -> poll
113	            // every cycle forever (observed: FP-class donor sparsity on
114	            // cholesky hung the sim with zero injections). Enforce a
115	            // minimum +1-cycle backoff on reject.
116	            unsigned next = inter_fault_cycles_dist(rng);
117	            if (faults_injected_count == before)  // no fault landed this try
118	                next = std::max(next, (unsigned)1);
119	            Cycles next_cycle = cpu->curCycle() + Cycles(next);
120	            if (last_clock == Cycles(0) || next_cycle <= last_clock)
121	                scheduleAttackEvent(Cycles(next));
122	        }
123	    }
