125	    void
126	    CHAOSRenameMap::processFault(ThreadID tid)
127	    {
128	        if (max_faults != 0 && faults_injected_count >= max_faults) return;
129	
130	        gem5::ThreadContext *thread_context = cpu->getContext(tid);
131	        if (!thread_context) return;
132	        gem5::BaseISA *isa = thread_context->getIsaPtr();
133	        if (!isa) return;
134	
135	        const auto &reg_classes = isa->regClasses();
136	        gem5::RegClassType target_class = gem5::IntRegClass;
137	        if (reg_target_class == RegClassSel::FloatingPoint)
138	            target_class = gem5::FloatRegClass;
139	        else if (reg_target_class == RegClassSel::Vector)
140	            target_class = gem5::VecRegClass;
141	        const gem5::RegClass *reg_class = reg_classes[target_class];
142	        if (!reg_class || reg_class->numRegs() == 0) {
143	            stats->numLegalityRejects++; return;
144	        }
145	
146	        int arch_idx = target_arch_idx;
147	        if (arch_idx < 0 || arch_idx >= (int)reg_class->numRegs()) {
148	            // method1-formal fix: random sampling on sparse classes (FP on
149	            // numeric kernels) mostly hits unmapped regs (observed 2.3M
150	            // rejects, 0 injections). SCAN the class for regs with an
151	            // ACTIVE mapping (like CHAOSFreeList's RAT scan) and pick
152	            // among those; fall back to random if none active.
153	            int n_arch = (int)reg_class->numRegs();
154	            std::vector<int> active;
155	            active.reserve(n_arch);
156	            for (int cand = 0; cand < n_arch; ++cand) {
157	                gem5::RegId cr(*reg_class, cand);
158	                const gem5::RegId cf = cr.flatten(*isa);
159	                if (cpu->frontRenameMap()[tid].lookup(cf)) active.push_back(cand);
160	            }
161	            if (active.empty()) { stats->numLegalityRejects++; return; }
162	            arch_idx = active[std::uniform_int_distribution<int>(
163	                0, (int)active.size() - 1)(rng)];
164	        }
165	        gem5::RegId arch_reg(*reg_class, arch_idx);
166	        const gem5::RegId flat = arch_reg.flatten(*isa);
167	
168	        // Read current mapping.
169	        PhysRegIdPtr old_phys = cpu->frontRenameMap()[tid].lookup(flat);
170	        if (!old_phys) {
171	            // not mapped yet (e.g. a random FP arch reg with no active
172	            // mapping — common on FP-sparse kernels). Count so the
173	            // attempt is observable (was a silent return).
174	            stats->numLegalityRejects++; return;
175	        }
176	        int old_phys_idx = old_phys->index();
177	
178	        int new_phys_idx = old_phys_idx;
179	        uint64_t mask = 0;
180	
181	        if (fi_mode == Mode::MapBitFlip) {
182	            // Flip a bit of the physRegIdx. Build the mask.
183	            mask = fault_mask;
184	            if (mask == 0) {
185	                // random one bit within a plausible physRegIdx width (<= 64 bits)
186	                std::uniform_int_distribution<int> bitDist(0, 7);
187	                mask = 1ULL << bitDist(rng);
188	            }
189	            new_phys_idx = old_phys_idx ^ (int)mask;
190	            // Legality check: new idx must be a valid physReg of this class.
191	            // PhysRegFile accessor gives the count; reject if out of range.
192	            size_t n_phys = 0;
193	            if (reg_target_class == RegClassSel::Integer)
194	                n_phys = cpu->physRegFile().numIntPhysRegs();
195	            else if (reg_target_class == RegClassSel::FloatingPoint)
196	                n_phys = cpu->physRegFile().numFloatPhysRegs();
197	            else
198	                n_phys = cpu->physRegFile().numVecPhysRegs();
199	            if (new_phys_idx < 0 || (size_t)new_phys_idx >= n_phys) {
200	                // Out of range — would SimulatorError. Reject (legality).
201	                stats->numLegalityRejects++;
202	                if (write_log) {
203	                    *(log_stream->stream())
204	                        << "Cycle: " << cpu->curCycle()
205	                        << " map_bitflip REJECT: old_phys=" << old_phys_idx
206	                        << " mask=0x" << std::hex << mask << std::dec
207	                        << " -> new_phys=" << new_phys_idx
208	                        << " out of range (n_phys=" << n_phys << ")\n";
209	                }
210	                return;
211	            }
212	            // Construct the new physRegId by index (PhysRegFile accessor).
213	            PhysRegIdPtr new_phys = nullptr;
214	            if (reg_target_class == RegClassSel::Integer)
215	                new_phys = cpu->physRegFile().intPhysRegId(new_phys_idx);
216	            else if (reg_target_class == RegClassSel::FloatingPoint)
217	                new_phys = cpu->physRegFile().floatPhysRegId(new_phys_idx);
218	            else
219	                new_phys = cpu->physRegFile().vecPhysRegId(new_phys_idx);
220	            if (!new_phys) { stats->numLegalityRejects++; return; }
221	            cpu->frontRenameMap()[tid].setEntry(flat, new_phys);
222	            stats->numMapBitFlips++;
223	        } else if (fi_mode == Mode::F5Substitute) {
224	            // method1 history residue: point this arch reg at ANOTHER currently-
225	            // allocated physReg (steal a donor's mapping). Enumerate other arch
226	            // regs of the same class, pick one whose lookup is non-null and
227	            // != old_phys.
228	            int donor_arch = -1;
229	            PhysRegIdPtr donor_phys = nullptr;
230	            int n_arch = reg_class->numRegs();
231	            // try up to n_arch random donors
232	            for (int tries = 0; tries < n_arch; ++tries) {
233	                int cand = std::uniform_int_distribution<int>(0, n_arch - 1)(rng);
234	                if (cand == arch_idx) continue;
235	                gem5::RegId cand_reg(*reg_class, cand);
236	                const gem5::RegId cand_flat = cand_reg.flatten(*isa);
237	                PhysRegIdPtr pp = cpu->frontRenameMap()[tid].lookup(cand_flat);
238	                if (pp && pp->index() != old_phys_idx) {
239	                    donor_arch = cand;
240	                    donor_phys = pp;
241	                    break;
242	                }
243	            }
244	            if (!donor_phys) {
245	                // No suitable donor — reject (legality, no residue possible now).
246	                stats->numLegalityRejects++;
247	                if (write_log) {
248	                    *(log_stream->stream())
249	                        << "Cycle: " << cpu->curCycle()
250	                        << " f5_substitute REJECT: no donor arch reg with a "
251	                        << "live mapping != self (arch=" << arch_idx << ")\n";
252	                }
253	                return;
254	            }
255	            new_phys_idx = donor_phys->index();
256	            // setEntry: point arch_reg at donor's physReg (double-occupancy =
257	            // method1 history residue — reads of arch_reg now return donor's value).
258	            cpu->frontRenameMap()[tid].setEntry(flat, donor_phys);
259	            stats->numF5Substitutes++;
260	            if (write_log) {
261	                *(log_stream->stream())
262	                    << "Cycle: " << cpu->curCycle()
263	                    << " f5_substitute: ArchReg[" << arch_idx << "] -> "
264	                    << "PhysReg[" << new_phys_idx << "] (stolen from donor arch "
265	                    << donor_arch << ", was PhysReg[" << old_phys_idx << "])\n";
266	            }
267	        } else if (fi_mode == Mode::F4FieldStuck) {
268	            // Persistently pin arch_reg to a wrong physReg. Arm a stuck mapping
269	            // that checkPermanent re-applies after subsequent rewrites.
270	            // For the initial application, substitute a donor (same as F5) then
271	            // record it as stuck.
272	            int n_arch = reg_class->numRegs();
273	            int donor_arch = -1;
274	            PhysRegIdPtr donor_phys = nullptr;
275	            for (int tries = 0; tries < n_arch; ++tries) {
276	                int cand = std::uniform_int_distribution<int>(0, n_arch - 1)(rng);
277	                if (cand == arch_idx) continue;
278	                gem5::RegId cand_reg(*reg_class, cand);
279	                const gem5::RegId cand_flat = cand_reg.flatten(*isa);
280	                PhysRegIdPtr pp = cpu->frontRenameMap()[tid].lookup(cand_flat);
281	                if (pp && pp->index() != old_phys_idx) {
282	                    donor_arch = cand;
283	                    donor_phys = pp;
284	                    break;
285	                }
286	            }
287	            if (!donor_phys) { stats->numLegalityRejects++; return; }
288	            new_phys_idx = donor_phys->index();
289	            cpu->frontRenameMap()[tid].setEntry(flat, donor_phys);
290	            stuck_mappings[{tid, arch_idx}] = {arch_idx, new_phys_idx};
291	            stats->numF4FieldStuck++;
292	            if (write_log) {
293	                *(log_stream->stream())
294	                    << "Cycle: " << cpu->curCycle()
295	                    << " f4_field_stuck: ArchReg[" << arch_idx << "] pinned to "
296	                    << "PhysReg[" << new_phys_idx << "] (donor arch " << donor_arch
297	                    << ", was " << old_phys_idx << ")\n";
298	            }
299	        }
300	
301	        stats->numFaultsInjected++;
302	        ++faults_injected_count;
303	        writeLog(modeToString(fi_mode), tid, arch_idx, old_phys_idx,
304	                 new_phys_idx, mask);
305	    }
