307	    void
308	    CHAOSRenameMap::checkPermanent()
309	    {
310	        // Re-apply f4_field_stuck mappings (survive subsequent rewrites — G2).
311	        gem5::BaseISA *isa = cpu->getContext(0) ? cpu->getContext(0)->getIsaPtr() : nullptr;
312	        if (!isa) {
313	            schedule(periodicCheck, cpu->clockEdge(cpu->curCycle() + Cycles(100000)));
314	            return;
315	        }
316	        const auto &reg_classes = isa->regClasses();
317	        gem5::RegClassType target_class = gem5::IntRegClass;
318	        if (reg_target_class == RegClassSel::FloatingPoint)
319	            target_class = gem5::FloatRegClass;
320	        else if (reg_target_class == RegClassSel::Vector)
321	            target_class = gem5::VecRegClass;
322	        const gem5::RegClass *reg_class = reg_classes[target_class];
323	        if (!reg_class) {
324	            schedule(periodicCheck, cpu->clockEdge(cpu->curCycle() + Cycles(100000)));
325	            return;
326	        }
327	        for (auto &kv : stuck_mappings) {
328	            ThreadID tid = kv.first.first;
329	            int arch_idx = kv.first.second;
330	            int stuck_phys_idx = kv.second.phys_idx;
331	            if ((size_t)arch_idx >= reg_class->numRegs()) continue;
332	            gem5::RegId arch_reg(*reg_class, arch_idx);
333	            const gem5::RegId flat = arch_reg.flatten(*isa);
334	            // Re-fetch the stuck physRegId by index (the map entry may have been
335	            // overwritten by a legitimate rename; re-pin it).
336	            PhysRegIdPtr stuck_phys = nullptr;
337	            if (reg_target_class == RegClassSel::Integer)
338	                stuck_phys = cpu->physRegFile().intPhysRegId(stuck_phys_idx);
339	            else if (reg_target_class == RegClassSel::FloatingPoint)
340	                stuck_phys = cpu->physRegFile().floatPhysRegId(stuck_phys_idx);
341	            else
342	                stuck_phys = cpu->physRegFile().vecPhysRegId(stuck_phys_idx);
343	            if (stuck_phys) {
344	                cpu->frontRenameMap()[tid].setEntry(flat, stuck_phys);
345	            }
346	        }
347	        schedule(periodicCheck, cpu->clockEdge(cpu->curCycle() + Cycles(100000)));
348	    }
