    bool any_active = false;
    for (ThreadID tid = 0; tid < cpu->numThreads; ++tid) {
        gem5::ThreadContext *thread_context = cpu->getContext(tid);
        if (thread_context && thread_context->status() != ThreadContext::Halted) {
