/* GEMM kernel for SDC FI verification (plan §5.6D, Task 2.1).
 *
 * Multiply-accumulate matrix kernel: C = A*B with deterministic
 * pseudo-random operands. The checksum over the result matrix propagates
 * any FPU bit-flip that lands in an accumulator lane (a wrong product or
 * partial sum flows into the final checksum -> SDC).
 *
 * Variants: argv[1] = "float" (default) | "double". The float variant
 * accumulates in float then widens; the double variant keeps the full
 * double chain — the method3 anchor target (single-bit flip in the
 * double accumulate path, popcount median 28 comparable).
 *
 * Output: 16-hex checksum of the result matrix (same convention as
 * reg_chain / l1d_reduce). Golden: native (host gcc) run must equal the
 * gem5 no-injection run bit-exactly (deterministic data + -O2 with no
 * fast-math; FP ops are IEEE-exact so host == gem5).
 */
#include <unistd.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

static void put_hex(unsigned long v){ char b[16]; for(int i=15;i>=0;--i){unsigned d=v&0xf;b[i]=d<10?'0'+d:'a'+d-10;v>>=4;} write(1,b,16); write(1,"\n",1); }

#define N 48            /* matrix dimension: 48x48 = 2304 MACs/element-pair,
                           big enough for a long FPU pipeline residency,
                           small enough for fast SE runs */

static uint32_t rng_state = 0xC0FFEE11u;
static inline uint32_t xorshift32(void){uint32_t x=rng_state;x^=x<<13;x^=x>>17;x^=x<<5;rng_state=x;return x;}

/* deterministic integer operands -> exact float/double representations
   (no rounding ambiguity between host and gem5) */
static int32_t A[N*N], B[N*N];

int main(int argc, char **argv){
    int use_double = (argc>1 && !strcmp(argv[1],"double"));
    for (int i=0;i<N*N;i++){ A[i] = (int32_t)(xorshift32() % 2001) - 1000;
                             B[i] = (int32_t)(xorshift32() % 2001) - 1000; }
    unsigned long acc = 0;
    if (use_double) {
        static double C[N*N];
        for (int i=0;i<N;i++)
            for (int j=0;j<N;j++){
                double s = 0.0;
                for (int k=0;k<N;k++)
                    s += (double)A[i*N+k] * (double)B[k*N+j];
                C[i*N+j] = s;
            }
        /* checksum: fold the bit patterns (any bit flip in any accumulator
           lane lands in the fold with high probability) */
        for (int i=0;i<N*N;i++){
            uint64_t bits; memcpy(&bits, &C[i], 8);
            acc = acc*1315423911u + (unsigned long)(bits ^ (bits>>32));
        }
    } else {
        static float C[N*N];
        for (int i=0;i<N;i++)
            for (int j=0;j<N;j++){
                float s = 0.0f;
                for (int k=0;k<N;k++)
                    s += (float)A[i*N+k] * (float)B[k*N+j];
                C[i*N+j] = s;
            }
        for (int i=0;i<N*N;i++){
            uint32_t bits; memcpy(&bits, &C[i], 4);
            acc = acc*1315423911u + (unsigned long)(bits ^ (bits>>16));
        }
    }
    put_hex(acc);
    return 0;
}

